      if (доСтыка > к.перекрёстокБлиже) continue;
      const другая = поКлючу[сосед.ключ];
      const тут = наДороге(герой.дорога, герой.s);
      const туда = наДороге(другая, приткнуть(другая, сосед.sТам + к.шаг));
      const вбок = (туда.x - тут.x) * сторона;
